import {withAdminErrorBoundary,requirePermission,okResponse,errorResponse} from '@/lib/admin/authz';
import {PERMISSIONS} from '@/lib/admin/permissions';
import {checkIdempotency,completeIdempotency,releaseIdempotency,getRequiredIdempotencyKey} from '@/lib/admin/idempotency';
import {publicErrorMessage} from '@/lib/security/publicError';
import {inspectModelPublication,prepareModelPublicationTest,quoteModelPublicationTest,submitModelPublicationTest,recordModelPublicationTest,publishModel,readModelPublicationTest} from '@/lib/services/modelPublication';
import {invalidateActiveModelsCache} from '@/app/api/models/active/route';

export const runtime='nodejs';
export const dynamic='force-dynamic';

export const POST=withAdminErrorBoundary(async request=>{
  const body=await request.json().catch(()=>({}));
  const readOnly=['inspect','read_test'].includes(body.action);
  const guard=await requirePermission(request,readOnly ? PERMISSIONS.modelsRead : PERMISSIONS.modelsWrite);
  if(!guard.ok)return guard.response;
  const actions={inspect:inspectModelPublication,prepare_test:prepareModelPublicationTest,quote_test:quoteModelPublicationTest,submit_test:submitModelPublicationTest,record_test:recordModelPublicationTest,publish:publishModel,read_test:readModelPublicationTest};
  if(!actions[body.action] || !body.modelId)return errorResponse('VALIDATION_ERROR','请选择模型及有效操作',422,guard.requestId);
  const key=getRequiredIdempotencyKey(request);
  if(!readOnly && !key)return errorResponse('IDEMPOTENCY_REQUIRED','操作必须携带幂等标识',422,guard.requestId);
  const idem=readOnly ? null : await checkIdempotency({scope:`model_publication:${body.action}`,key,actorId:guard.user.id});
  if(idem && !idem.allowed)return idem.cachedResponse ? okResponse(idem.cachedResponse,guard.requestId) : errorResponse('CONFLICT','操作正在处理',409,guard.requestId);
  try{
    const result=await actions[body.action]({...body,actor:guard.user,idempotencyKey:key,requestId:guard.requestId});
    if(body.action==='publish')invalidateActiveModelsCache();
    if(idem)await completeIdempotency(idem.keyHash,result);
    return okResponse(result,guard.requestId);
  }catch(error){
    if(idem)await releaseIdempotency(idem.keyHash);
    return errorResponse(error.code || 'MODEL_PUBLICATION_FAILED',publicErrorMessage(error,'操作尚未完成，请处理阻塞项'),error.code==='FORBIDDEN' ? 403 : 422,guard.requestId);
  }
});

import { withAdminErrorBoundary, requirePermission, okResponse, errorResponse } from '@/lib/admin/authz';
import { PERMISSIONS } from '@/lib/admin/permissions';
import {
  listProviderModelsByModelId,
  getRoutingPolicy,
  upsertRoutingPolicy,
  upsertProviderModel,
  deleteProviderModel,
  getCanonicalModelById,
  listProviders,
  listCanonicalModels,
} from '@/lib/application/dataAccess.js';
import { logAudit } from '@/lib/admin/audit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

async function handleGET(request) {
  const guard = await requirePermission(request, PERMISSIONS.modelsRead);
  if (!guard.ok) return guard.response;

  const { searchParams } = new URL(request.url);
  const modelId = searchParams.get('modelId');

  if (!modelId) {
    // 列出所有规范模型及其关联渠道数量
    const models = await listCanonicalModels();
    const providers = await listProviders();
    return okResponse({ models, providers }, guard.requestId);
  }

  const [canonicalModel, providerModels, routingPolicy, providers] = await Promise.all([
    getCanonicalModelById(modelId),
    listProviderModelsByModelId(modelId),
    getRoutingPolicy(modelId),
    listProviders(),
  ]);

  return okResponse({
    canonicalModel,
    providerModels,
    routingPolicy: routingPolicy || {
      model_id: modelId,
      routing_mode: 'balanced',
      weights: { cost: 0.4, success_rate: 0.3, speed: 0.2, capacity: 0.1 },
      circuit_breaker_config: { failure_threshold: 3, cooling_period_sec: 60 },
      failover_enabled: true,
    },
    availableProviders: providers,
  }, guard.requestId);
}

async function handlePOST(request) {
  const guard = await requirePermission(request, PERMISSIONS.modelsWrite);
  if (!guard.ok) return guard.response;

  const body = await request.json().catch(() => ({}));
  const { type = 'provider_model', data } = body;

  if (type === 'policy') {
    if (!data?.model_id) {
      return errorResponse('VALIDATION_ERROR', 'model_id 为必填项', 422, guard.requestId);
    }
    const updatedPolicy = await upsertRoutingPolicy(data);
    await logAudit({
      actor: guard.user,
      action: 'models.routing_policy_update',
      targetType: 'routing_policy',
      targetId: data.model_id,
      riskLevel: 'medium',
      after: updatedPolicy,
    });
    return okResponse({ routingPolicy: updatedPolicy }, guard.requestId);
  }

  if (!data?.model_id || !data?.provider_id) {
    return errorResponse('VALIDATION_ERROR', 'model_id 与 provider_id 均为必填项', 422, guard.requestId);
  }

  const updatedChannel = await upsertProviderModel(data);
  await logAudit({
    actor: guard.user,
    action: 'models.channel_mapping_upsert',
    targetType: 'provider_model',
    targetId: updatedChannel.id,
    riskLevel: 'medium',
    after: updatedChannel,
  });

  return okResponse({ providerModel: updatedChannel }, guard.requestId);
}

async function handleDELETE(request) {
  const guard = await requirePermission(request, PERMISSIONS.modelsWrite);
  if (!guard.ok) return guard.response;

  const { searchParams } = new URL(request.url);
  const id = searchParams.get('id');
  if (!id) {
    return errorResponse('VALIDATION_ERROR', '请指定要删除的渠道映射 ID', 422, guard.requestId);
  }

  await deleteProviderModel(id);
  await logAudit({
    actor: guard.user,
    action: 'models.channel_mapping_delete',
    targetType: 'provider_model',
    targetId: id,
    riskLevel: 'medium',
  });

  return okResponse({ success: true, id }, guard.requestId);
}

export const GET = withAdminErrorBoundary(handleGET);
export const POST = withAdminErrorBoundary(handlePOST);
export const DELETE = withAdminErrorBoundary(handleDELETE);

import { withAdminErrorBoundary, requirePermission, okResponse, errorResponse } from '@/lib/admin/authz';
import { PERMISSIONS } from '@/lib/admin/permissions';
import { getProviderAdapter } from '@/lib/adapters/index';
import { getProviderModelById } from '@/lib/application/dataAccess.js';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

async function handlePOST(request) {
  const guard = await requirePermission(request, PERMISSIONS.providersRead);
  if (!guard.ok) return guard.response;

  const body = await request.json().catch(() => ({}));
  const channelId = body.channelId || body.channel_id;

  if (!channelId) {
    return errorResponse('VALIDATION_ERROR', '请指定要测试的渠道 ID (channelId)', 422, guard.requestId);
  }

  const channel = await getProviderModelById(channelId);
  if (!channel) {
    return errorResponse('NOT_FOUND', '未找到对应的供应商模型渠道', 404, guard.requestId);
  }

  const start = Date.now();
  try {
    const adapter = await getProviderAdapter(channel.provider_id);
    const healthResult = await adapter.healthCheck();
    const latencyMs = Date.now() - start;

    return okResponse({
      success: true,
      channelId,
      providerId: channel.provider_id,
      providerModelId: channel.provider_model_id,
      latencyMs,
      message: `渠道测试成功 (${healthResult.status || 'OK'})`,
      details: healthResult,
    }, guard.requestId);
  } catch (error) {
    const latencyMs = Date.now() - start;
    return okResponse({
      success: false,
      channelId,
      providerId: channel.provider_id,
      providerModelId: channel.provider_model_id,
      latencyMs,
      message: '渠道探测请求失败',
      errorCode: /^[A-Z0-9_:-]{2,80}$/.test(String(error?.code || '')) ? String(error.code) : 'CHANNEL_PROBE_ERROR',
    }, guard.requestId);
  }
}

